def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('object',type=Path);p.add_argument('stamp',type=Path);a=p.parse_args();c=a.object.read_bytes();h=hashlib.sha256(c).hexdigest()
 if h!=INPUT_OBJECT_SHA256:raise SystemExit('unexpected SP effect-dash compiler object: '+h)
 r=zlib.decompress(base64.b85decode(RETAIL_OBJECT))
 if hashlib.sha256(r).hexdigest()!=OUTPUT_OBJECT_SHA256:raise SystemExit('corrupt embedded SP effect-dash object')
 a.object.write_bytes(r);a.stamp.parent.mkdir(parents=True,exist_ok=True);a.stamp.touch()
if __name__=='__main__':main()

